function validate([logs, n]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is a whole number from 2 to 100.';
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 10000) return 'logs needs 1 to 10^4 entries.';
  const times = new Set(), pairs = new Set();
  for (const log of logs) {
    if (!Array.isArray(log) || log.length !== 3 || !log.every(Number.isInteger)) return 'Each entry is [timestamp, x, y] of whole numbers.';
    const [timestamp, x, y] = log;
    if (timestamp < 0 || timestamp > 1e9) return 'Timestamps are from 0 to 10^9.';
    if (x < 0 || x >= n || y < 0 || y >= n) return 'x and y are people from 0 to n - 1.';
    if (x === y) return 'x and y must be different people.';
    if (times.has(timestamp)) return 'Timestamps must be distinct.';
    times.add(timestamp);
    const key = Math.min(x, y) * 100 + Math.max(x, y);
    if (pairs.has(key)) return 'Each pair of people appears at most once.';
    pairs.add(key);
  }
  return null;
}

