function earliestAcq(logs, n) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (person) => {
    while (parent[person] !== person) {
      parent[person] = parent[parent[person]];
      person = parent[person];
    }
    return person;
  };
  const ordered = [...logs].sort((a, b) => a[0] - b[0]);
  let groups = n;
  for (const [timestamp, x, y] of ordered) {
    const rootX = find(x);
    const rootY = find(y);
    if (rootX === rootY) {
      continue;
    }
    parent[rootX] = rootY;
    groups--;
    if (groups === 1) {
      return timestamp;
    }
  }
  return -1;
}

