function earliestAcq(logs, n) {
  const times = logs.map(log => log[0]).sort((a, b) => a - b);
  for (const time of times) {
    const adjacency = Array.from({ length: n }, () => []);
    for (const [t, x, y] of logs) {
      if (t <= time) { adjacency[x].push(y); adjacency[y].push(x); }
    }
    const reached = new Array(n).fill(false);
    const stack = [0];
    reached[0] = true;
    let count = 1;
    while (stack.length) {
      const person = stack.pop();
      for (const other of adjacency[person]) {
        if (!reached[other]) { reached[other] = true; count++; stack.push(other); }
      }
    }
    if (count === n) return time;
  }
  return -1;
}

