function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 5);
  // Sometimes keep one person out of every friendship so that the answer is -1.
  const loner = rand() < 0.25 ? Math.floor(rand() * n) : -1;
  const pairs = [];
  for (let x = 0; x < n; x++) {
    for (let y = x + 1; y < n; y++) {
      if (x !== loner && y !== loner) pairs.push(rand() < 0.5 ? [x, y] : [y, x]);
    }
  }
  for (let i = pairs.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }
  const want = large ? Math.min(pairs.length, 2000) : Math.max(1, Math.floor(rand() * (pairs.length + 1)));
  const chosen = pairs.slice(0, Math.max(1, Math.min(want, pairs.length)));
  if (!chosen.length) chosen.push([0, 1]);
  const span = large ? 1e9 : 40;
  const used = new Set();
  const logs = chosen.map(([x, y]) => {
    let timestamp;
    do { timestamp = Math.floor(rand() * (span + 1)); } while (used.has(timestamp));
    used.add(timestamp);
    return [timestamp, x, y];
  });
  return [logs, n];
}
